n.bookSourceComment:
/*
需搜索全名，且至少三个字
2025.02.05
by 天天的鸟蛋蛋 
正文webView 关耳
正文解密 水镜绘纱
发现+整合正文 另一个书友圈
*/
// 由 RosiaP'ng 提供支持
function decoderosiapng(dd) {
  // 第一步：解码输入数据
  let decodedData = CryptoJS.enc.Base64.parse(dd).toString(CryptoJS.enc.Utf8);
  // 第二步：计算偏移量并确定起始和结束位置
  let offset = Number(decodedData.slice(8, 11));
  let start = offset + 11;
  let end = decodedData.length - offset;
  // 第三步：检查起始位置是否小于结束位置，以避免无效切片
  if (start < end) {
    // 第四步：通过替换字符处理数据
    let processedData = decodedData
      .slice(start, end)
      .replace(/_/g, "8L3A+")
      .replace(/-/g, "PHA+");
    // 第五步：解码处理后的数据
    return CryptoJS.enc.Base64.parse(processedData).toString(CryptoJS.enc.Utf8);;
  }
  // 如果条件不满足，返回 null 或按需处理
  return null;
}

